    username: 'david_builds',
    fullname: 'David Garcia'
};

const mockPosts = [
    {
        _id: 'post_1',
        content: 'Exploring the amazing architecture of the new downtown library. A great place for quiet study and inspiration. #architecture #library #study',
        images: [{ url: 'https://placehold.co/600x400/CCCCCC/FFFFFF?text=Library+Building' }],
        likes: [mockUserAlex],
        comments: [],
        user: mockUserSamantha,
        createdAt: new Date(Date.now() - 1000 * 60 * 15).toISOString()
    },
    {
        _id: 'post_2',
        content: 'Finally finished my latest coding project! Building a full-stack MERN application from scratch was a challenge, but so rewarding. #coding #javascript #react',
        images: [{ url: 'https://placehold.co/600x400/90EE90/FFFFFF?text=Code+on+Screen' }],
        likes: [mockUserSamantha, mockUserDavid],
        comments: [],
        user: mockUserAlex,
        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 3).toISOString()
    },
    {
        _id: 'post_3',
        content: 'Weekend project: built a custom bookshelf! Nothing beats the feeling of creating something with your own hands. #DIY #woodworking #craft',
        images: [{ url: 'https://placehold.co/600x400/DEB887/FFFFFF?text=Wooden+Bookshelf' }],
        likes: [],
        comments: [],
        user: mockUserDavid,
        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 8).toISOString()
    },
     {
        _id: 'post_4',
        content: 'A beautiful day for a trip to the coast. The ocean always helps clear my mind. #travel #ocean #beachlife',
        images: [{ url: 'https://placehold.co/600x400/87CEEB/FFFFFF?text=Ocean+View' }],
        likes: [mockUserDavid, mockUserAlex],
        comments: [],
        user: mockUserSamantha,
        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString()
    }
];

// --- END OF FAKE DATA ---


const initialState = {
    loading: false,
    posts: mockPosts,      // Use the mock data
    result: mockPosts.length, // Set the result count
    page:2,

}

const postReducer = (state = initialState, action) => {
  switch (action.type) {
    case POST_TYPES.CREATE_POST:
      return {
        ...state,
        posts: [action.payload, ...state.posts],
      };

    case POST_TYPES.LOADING_POST:
      return {
        ...state,
        loading: action.payload,
      };

    case POST_TYPES.GET_POSTS:
      return {
        ...state,
        posts: action.payload.posts,
        result: action.payload.result,
        page: action.payload.page,
      };

    case POST_TYPES.UPDATE_POST:
      return {
        ...state,
        posts: EditData(state.posts, action.payload._id, action.payload),
      };

    case POST_TYPES.DELETE_POST:
      return {
        ...state,
        posts: DeleteData(state.posts, action.payload._id),
      };

    case POST_TYPES.REPORT_POST:
      return {
        ...state,
        posts: EditData(state.posts, action.payload._id, action.payload),
      };

    default:
      return state;
  }
};

export default postReducer;
